<section class="page-heading"><span class="eyebrow">Administration</span><h1>Manage schemes</h1><p>Draft or deactivate entries that are inaccurate or out of date.</p></section><div class="admin-actions"><a class="button" href="<?=e(url('admin_scheme'))?>">Create a scheme</a><a href="<?=e(url('admin'))?>">← Dashboard</a></div><?php if(!$schemes): ?><div class="empty-state">No schemes are recorded.</div><?php else: ?><div class="table-wrap"><table><thead><tr><th>Scheme</th><th>Status</th><th>Review</th><th>Updated</th><th></th></tr></thead><tbody><?php foreach($schemes as $scheme): ?><tr><td><?=e($scheme['title'])?><?=$scheme['is_demo']?' <span class="badge badge-demo">DEMO</span>':''?></td><td><?=e($scheme['status'])?></td><td><?=e(str_replace('_',' ',$scheme['verification_status']))?></td><td><?=e($scheme['updated_at'])?></td><td><a href="<?=e(url('admin_scheme',['id'=>$scheme['id']]))?>">Edit</a></td></tr><?php endforeach; ?></tbody></table></div><div class="pagination"><a href="<?=e(url('admin_schemes',['p'=>max(1,$pageNo-1)]))?>">← Previous</a><span>Page <?=e($pageNo)?></span><a href="<?=e(url('admin_schemes',['p'=>$pageNo+1]))?>">Next →</a></div><?php endif; ?>
